{
  "name": "arkive-compact",
  "version": "1.3.0",
  "description": "Lossless context compression plugin for OpenCode.",
  "type": "module",
  "module": "src/index.ts",
  "main": "src/index.ts",
  "exports": {
    ".": {
      "import": "./src/index.ts"
    },
    "./tui": {
      "import": "./src/tui.ts"
    },
    "./server": {
      "import": "./src/index.ts"
    }
  },
  "files": [
    "index.ts",
    "tui.ts",
    "src",
    "LICENSE.md",
    "NOTICE.md"
  ],
  "license": "SEE LICENSE IN LICENSE.md",
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit -p ../../tsconfig.json",
    "lint": "eslint src test",
    "format": "prettier --write src"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "codex",
    "openai",
    "gemini",
    "cursor",
    "ai",
    "llm",
    "plugin",
    "context",
    "compaction"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/imarshallwidjaja/magic-compact.git"
  },
  "bugs": {
    "url": "https://github.com/imarshallwidjaja/magic-compact/issues"
  },
  "homepage": "https://github.com/imarshallwidjaja/magic-compact#readme",
  "author": "imarshallwidjaja",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.30 <2"
  },
  "dependencies": {
    "@opencode-ai/sdk": "1.18.30",
    "@opencode/client": "2.0.28",
    "gpt-tokenizer": "3.4.0",
    "zod": "^4.4.3"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.30",
    "@opencode/plugin": "2.0.28"
  }
}
